```java
class Animal {
    //父类定义了有参构造器会覆盖掉默认的无参构造器
    public Animal (int name , int age) {
        this.name = name;
        this.age = age;
    }
}

class Dog  extends Animal {
    public Dog (int name , int age) {
        //子类在继承父类的时候会默认调用无参构造器 如果父类没有无参构造器 一定要在子类中指定父类的一种构造器
        super()
        this.name = name;
        this.age = age;
    }
}
```



