### 序列化与反序列化

java库中的`java.io.ObjectInputStraeam`和`java.io.ObjectOutputStraeam`提供的writeObject()和readObject()实现了序列化与反序列化

```java
package com.javaSerializeDemo;
import java.io.*;
import java.util.Arrays;
public class javaSerializedemo2 {
	//静态类
    public static class test implements Serializable {

        private String username;
        private String password;

        public String getPassword() {
            return password;
        }

        public void setPassword(String password) {
            this.password = password;
        }

        public String getUsername() {
            return username;
        }

        public void setUsername(String username) {
            this.username = username;
        }


    }

    public static void main(String[] args) {
        //创建字节数组输出流
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try {
        test test1 = new test();
        test1.setPassword("123456");
        test1.setUsername("admin");
	    //创建对象输出流 将转换的数据都存储到刚刚创建的字节数组输出流中
        ObjectOutputStream out = new ObjectOutputStream(baos);

        out.writeObject(test1);
        out.flush();
        out.close();

        System.out.println("序列化结果: " + "\t" +Arrays.toString(baos.toByteArray()));
        /* */
        ByteArrayInputStream bais = new ByteArrayInputStream(baos.toByteArray());

        ObjectInputStream in = new ObjectInputStream(bais);

        test test2 = (test) in.readObject();

        System.out.println("反序列化结果: " + "\t" + test2.getPassword() + "\t" + test2.getUsername());
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

}

```

